-- Reseed agent message bodies as markdown.
--
-- sql/072 shipped these as plain text with "•" bullets and bare paths, then was
-- rewritten to real markdown — but its INSERT is ON CONFLICT DO NOTHING, so the
-- rows already in the database kept the old text. The Inbox renders markdown
-- now, which is why the evidence lists collapsed onto one line and "/rates"
-- stayed inert. This carries the corrected bodies onto the existing rows.
--
-- Idempotent: re-running just rewrites the same bodies.

UPDATE messages SET body = E'Aetna''s provider directory stopped listing your Union Square office this morning. It listed both addresses on 2026-08-04 and only the Brooklyn one on 2026-08-11.\n\nEvidence — Aetna Plan-Net FHIR pull, as of 2026-08-11:\n- PractitionerRole 1720394857-aetna-01 → 115 W 30th St (present)\n- PractitionerRole 1720394857-aetna-02 → Union Square (absent, was present 08-04)\n\nThis is the second consecutive sweep, so it is a real delisting rather than a one-night gap. Nothing changed on our side — no roster submission went out in that window.\n\n[View the listing](/directory/providers/1720394857)' WHERE id = '00000000-0000-4000-8000-000000018101';
UPDATE messages SET body = E'Cigna''s published in-network rate for 90837 sits below Oxford''s for the same code and setting.\n\nMedian, office setting, current published files:\n- Oxford  $154.30\n- Cigna   $142.00  — 8% lower\n\nYour list price for 90837 is $150.00, so Cigna is the one payer of the two publishing under what you charge.\n\nTo be clear about what this is: published rates, not remits. Leuk does not store paid-per-code data yet, so I cannot tell you what Cigna has actually paid you — only what it says it pays.\n\n[Published rates](/rates)' WHERE id = '00000000-0000-4000-8000-000000018102';
UPDATE messages SET body = 'Is Cigna low across the board, or just on that code?' WHERE id = '00000000-0000-4000-8000-000000018103';
UPDATE messages SET body = 'Across the board, but by less: 90834 is 6% under Oxford and 99214 is 3% under. 90837 is the widest gap and the code you bill most, so it is the one worth raising.' WHERE id = '00000000-0000-4000-8000-000000018104';
UPDATE messages SET body = E'Two progress notes have been unsigned longer than 72 hours:\n\n- Casey Morgan — session 2026-08-07, drafted, unsigned 4 days\n- Jordan Lee — session 2026-08-08, drafted, unsigned 3 days\n\nBoth have complete transcripts and drafted bodies, so signing is the only step left. I have not changed either note.' WHERE id = '00000000-0000-4000-8000-000000018105';
UPDATE messages SET body = E'Optum''s directory lists (212) 555-0143 for your Union Square office. That number is not on any of your practice locations in Leuk.\n\nOptum listing, as of 2026-08-09: (212) 555-0143\nLeuk locations: Union Square (212) 555-0190 · Brooklyn Heights (718) 555-0164\n\nA wrong number in a payer directory reads to a referrer as a practice that doesn''t pick up. I can''t see who submitted it or when — only what the directory currently publishes.\n\n[Your practice locations](/settings/locations)' WHERE id = '00000000-0000-4000-8000-000000018106';
UPDATE messages SET body = E'For 90834 (45-min therapy), Oxford''s published in-network median is $128.60 against Cigna''s $115.75 — Oxford pays about 11% more for the same code.\n\nMedian, office setting, current published files:\n- Oxford  $128.60  (IQR $121.00–$137.40)\n- Cigna   $115.75  (IQR $108.20–$124.00)\n\nWorth knowing before your next Cigna conversation. This is published rate only — I can''t see what either has actually remitted to you.\n\n[Published rates](/rates)' WHERE id = '00000000-0000-4000-8000-000000018107';
UPDATE messages SET body = E'An intake note from 2026-08-05 is signed but carries no diagnosis code. Every other intake in the last 90 days has one.\n\nWithout a code the superbill can''t be generated and the claim will reject on submission. The note itself is complete — this is a missing field, not a missing session.' WHERE id = '00000000-0000-4000-8000-000000018108';
UPDATE messages SET body = E'You do not appear in Emblem''s 2026 behavioral-health directory. You appear in Aetna''s, Cigna''s, Oxford''s and Healthfirst''s.\n\nEmblem pull, as of 2026-08-06: no PractitionerRole for NPI 1720394857.\n\nI can see the listing is absent. I cannot see whether you are contracted with Emblem and merely unlisted, or not contracted at all — Leuk holds no contract data. If you believe you''re in-network, this is a directory problem worth escalating; if you''re not, it''s a gap worth pricing.\n\n[Your network participation](/networks)' WHERE id = '00000000-0000-4000-8000-000000018109';
UPDATE messages SET body = E'Your list price for 90791 (diagnostic intake) is $180.00. Every payer we track publishes above that for the same code — the lowest is Healthfirst at $186.40, the highest Oxford at $232.15.\n\nA list price below the published in-network rate caps what you can collect from self-pay clients and anchors low in any negotiation.\n\n[Your service catalog](/catalog)' WHERE id = '00000000-0000-4000-8000-000000018110';
UPDATE messages SET body = 'Hi Jordan — we have a new Oxford card on file for you starting 8/1. Nothing needed on your end; your next session bills to the new plan automatically.' WHERE id = '00000000-0000-4000-8000-000000018111';
UPDATE messages SET body = 'Sorry about the trouble getting in on Monday — the room link had expired. I''ve reissued it and the new one is on your appointment in the portal.' WHERE id = '00000000-0000-4000-8000-000000018112';
UPDATE messages SET body = 'Hi Ruth — the Thursday insomnia group moves to 6:30 PM starting next week so people can get there after work. Same room, same eight weeks.' WHERE id = '00000000-0000-4000-8000-000000018113';
